        usage = event.usage;
      } else if (event.type === "turn.failed") {
        turnError = event.error.message;
      } else if (event.type === "error") {
        turnError = event.message;
      }
    }
  } catch (error) {
    turnError = error instanceof Error ? error.message : String(error);
  }

